78	    /**
79	     * Reports the owner's bulk-signup warning: {@code true} when more than 80 owners had already
80	     * been created on this owner's registration business day at the time it was created. Treats a
81	     * missing value (owners created before this rule existed) as {@code false}.
82	     */
83	    default boolean bulkSignupWarning(Owner owner) {
84	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
85	    }
86	
87	    /**
88	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
89	     * in {@code customerCode}, derived at read time. Returns {@code null} when no customer code has
90	     * been assigned.
91	     */
92	    default Integer checkDigit(Owner owner) {
93	        String customerCode = owner.getCustomerCode();
94	        if (customerCode == null) {
95	            return null;
96	        }
97	        int sum = 0;
98	        boolean dbl = true;
99	        for (int i = customerCode.length() - 1; i >= 0; i--) {
100	            char c = customerCode.charAt(i);
101	            if (c < '0' || c > '9') {
102	                continue;
103	            }
104	            int d = c - '0';
105	            if (dbl) {
106	                d *= 2;
107	                if (d > 9) {
108	                    d -= 9;
109	                }
110	            }
111	            sum += d;
112	            dbl = !dbl;
113	        }
114	        return (10 - (sum % 10)) % 10;
115	    }
116	
117	    /**
118	     * Derives the owner's membership points: starts at 0, adds 2 when an email is present, adds 1
119	     * when the owner had no namesakes at creation ({@code namesakeCount == 0}), adds 2 when the
120	     * owner belongs to a household of 3 or more members ({@code householdSize >= 3}, counted at
121	     * creation by {@code AssignHouseholdSize}), and adds 3 when the owner's tenure (days since
122	     * {@code registrationDate}) exceeds 365.
123	     */
124	    default int membershipPoints(Owner owner) {
125	        int points = 0;
126	        if (hasEmail(owner)) {
127	            points += 2;
128	        }
129	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
130	            points += 1;
131	        }
132	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
133	            points += 2;
134	        }
135	        if (tenureDays(owner) > 365) {
136	            points += 3;
137	        }
138	        return points;
139	    }
140	
141	    /**
142	     * Maps the owner's {@link #membershipPoints(Owner) membership points} to a numeric level:
143	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
144	     */
145	    default int membershipLevel(Owner owner) {
146	        int points = membershipPoints(owner);
147	        if (points <= 1) {
148	            return 1;
149	        }
150	        if (points <= 3) {
151	            return 2;
152	        }
153	        if (points <= 5) {
154	            return 3;
155	        }
156	        return 4;
157	    }
158	
159	    /**
160	     * The owner's tenure in whole days: the number of days from its {@code registrationDate} to
161	     * today. Returns 0 when no registration date is stored (or it lies in the future), so an owner
162	     * with no recorded tenure never qualifies for the tenure-gated points.
163	     */
164	    default long tenureDays(Owner owner) {
165	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
166	        if (registrationDate == null) {
167	            return 0;
168	        }
169	        long days = java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
170	        return Math.max(days, 0);
171	    }
172	
173	    /**
174	     * Derives the owner's locality (region) at read time from the region-and-hash
175	     * {@code customerCode}: its {@code REGION} prefix (e.g. {@code NSW} for {@code NSW-1A2B3C4D}),
176	     * so the region cannot drift from the identity every other derived value flows through. Owners
177	     * with no {@code customerCode} fall back to resolving the region directly. Both the parse and
178	     * the fallback (including the {@code UNKNOWN} sentinel) live in {@code OwnerCustomerCode}.
179	     */
180	    default String locality(Owner owner) {
181	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
182	            .regionOf(owner.getCustomerCode());
183	        return region != null ? region
184	            : org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
185	                .regionFor(owner);
186	    }
187	
188	    /**
189	     * Derives the owner's timezone at read time: the IANA name for the owner's
190	     * {@link #locality(Owner) locality} (region) from the fixed region-to-timezone table
191	     * (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane). Returns
192	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}), so the field is
193	     * absent for such owners.
194	     */
195	    default String timezone(Owner owner) {
196	        return org.springframework.samples.petclinic.rest.function.owner.OwnerLocality
197	            .timezoneForRegion(locality(owner));
198	    }
