3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for the owner address normalisation rule used across the
8	 * {@code POST /owners} pipeline: an address is canonicalised by trimming, collapsing internal
9	 * whitespace to single spaces, upper-casing, and expanding common abbreviations as whole words
10	 * ({@code ST}→{@code STREET}, {@code RD}→{@code ROAD}, {@code AVE}→{@code AVENUE}). So
11	 * {@code "  12  main  st "} canonicalises to {@code "12 MAIN STREET"} and {@code "7 elm ave"} to
12	 * {@code "7 ELM AVENUE"}.
13	 *
14	 * <p>Centralised here (rather than inlined) so its one consumer has a single definition to agree
15	 * on: {@link ValidateOwnerFields} stores the canonical value and rejects a value that is blank
16	 * once normalised.
17	 */
18	final class OwnerAddress {
19	
20	    /** Whole-word abbreviations expanded during normalisation. */
21	    private static final Map<String, String> ABBREVIATIONS = Map.of(
22	            "ST", "STREET",
23	            "RD", "ROAD",
24	            "AVE", "AVENUE");
25	
26	    private OwnerAddress() {
27	    }
28	
29	    /**
30	     * The stored/returned/compared form: trimmed, internal whitespace collapsed to single
31	     * spaces, upper-cased, with common abbreviations expanded as whole words. Returns an empty
32	     * string for a null or whitespace-only input.
33	     */
34	    static String normalize(String address) {
35	        if (address == null) {
36	            return "";
37	        }
38	        String trimmed = address.trim();
39	        if (trimmed.isEmpty()) {
40	            return "";
41	        }
42	        String[] tokens = trimmed.toUpperCase(Locale.ROOT).split("\\s+");
43	        StringBuilder sb = new StringBuilder();
44	        for (String token : tokens) {
45	            if (sb.length() > 0) {
46	                sb.append(' ');
47	            }
48	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
49	        }
50	        return sb.toString();
51	    }
52	}
