10	/**
11	 * Create-time guard for {@code POST /owners}: rejects a request that is missing or blank in
12	 * any required field (firstName, lastName, address, city, telephone) with a 400 whose body
13	 * lists the offending field names. Runs first in the pipeline and publishes the body for
14	 * {@link BuildOwner} once it is known to be complete.
15	 *
16	 * <p>Distinct from {@link ValidateOwner} (the {@code @Valid} declarative path used by
17	 * {@code PUT /owners/{ownerId}}) for two reasons the spec forces here:
18	 * <ul>
19	 * <li>the create spec requires the {@code errors} array shape
20	 *     ({@link MissingOwnerFieldsException}), not the {@code ProblemDetail} a bean-validation
21	 *     escalation produces; and</li>
22	 * <li>"blank" must be rejected, which the DTO constraints do not express — {@code city} and
23	 *     {@code address} carry only {@code @NotNull @Size(min = 1)}, so a whitespace-only value
24	 *     passes bean validation. Hence the explicit {@link #isBlank(String)} check and the
25	 *     deliberate absence of {@code @Valid} on the binding.</li>
26	 * </ul>
27	 */
28	public class ValidateOwnerFields {
29	
30	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
31	            throws MissingOwnerFieldsException {
32	        List<String> missing = new ArrayList<>();
33	        if (isBlank(request.getFirstName())) {
34	            missing.add("firstName");
35	        }
36	        if (isBlank(request.getLastName())) {
37	            missing.add("lastName");
