10	/**
11	 * Single source of truth for the owner "household" notion used by the {@code POST /owners}
12	 * pipeline. A household is keyed on {@code (lastName, postcode)}: two owners belong to the same
13	 * household when they share a last name (compared case-insensitively with collapsed whitespace)
14	 * and a postcode. The household identifier is <em>deterministic</em> — derived from those two
15	 * fields alone — so every owner with the same last name and postcode derives the same id
16	 * automatically, without any explicit linking step.
17	 *
18	 * <p>Centralised here (rather than inlined in {@link AssignHousehold} or
19	 * {@link CheckOwnerIdentityUnique}) so the id derivation cannot silently disagree about who
20	 * belongs together.
21	 */
22	final class OwnerHousehold {
23	
24	    private OwnerHousehold() {
25	    }
26	
27	    /**
28	     * A stable identifier for the household the request names, or {@code null} when the request
29	     * carries no postcode (an owner without a postcode belongs to no household).
30	     */
31	    static String deriveId(OwnerFieldsDto request) {
32	        return idFor(request.getLastName(), request.getPostcode());
33	    }
34	
35	    /**
36	     * A stable identifier for the household the existing owner belongs to, or {@code null} when it
37	     * has no postcode. Recomputed from {@code (lastName, postcode)} so it stays correct even for
38	     * records stored before household ids were assigned.
39	     */
40	    static String deriveId(Owner owner) {
41	        return idFor(owner.getLastName(), owner.getPostcode());
42	    }
43	
44	    /**
45	     * The household id for the given last name and postcode: the first 12 hex characters
46	     * (upper-cased) of SHA-256 over {@code normalizedLastName + '|' + postcode}. Deterministic, so
47	     * every member of the same household derives the same id. Returns {@code null} when the
48	     * postcode is absent or blank.
49	     */
50	    static String idFor(String lastName, String postcode) {
51	        if (postcode == null || postcode.isBlank()) {
52	            return null;
53	        }
54	        String key = normalize(lastName) + "|" + postcode;
55	        try {
56	            byte[] digest = MessageDigest.getInstance("SHA-256")
57	                    .digest(key.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder();
59	            for (byte b : digest) {
60	                sb.append(String.format("%02X", b));
61	            }
62	            return sb.substring(0, 12);
63	        }
64	        catch (NoSuchAlgorithmException ex) {
65	            throw new IllegalStateException("SHA-256 not available", ex);
66	        }
67	    }
68	
69	    /** The last-name comparison form: trimmed, internal whitespace collapsed, lower-cased. */
70	    static String normalize(String value) {
71	        if (value == null) {
72	            return "";
73	        }
74	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
75	    }
76	}
