18	    /** Maximum number of owners permitted in a single city. */
19	    private static final int CITY_CAPACITY = 50;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws CityAtCapacityException {
23	        String city = request.getCity();
24	        long count = ownerRepository.findAll().stream()
25	            .map(Owner::getCity)
26	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
27	            .count();
28	        if (count >= CITY_CAPACITY) {
29	            throw new CityAtCapacityException(city);
30	        }
31	    }
