1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Soft-duplicate detection for {@code POST /owners}. A request that cleared the hard-duplicate
10	 * guard ({@link CheckOwnerIdentityUnique}) is still created, but is flagged as a <em>possible</em>
11	 * duplicate when it shares an existing owner's {@code lastName} and {@code postcode} while carrying
12	 * a <em>different</em> telephone. The matching owner's id is recorded in {@code possibleDuplicateOf};
13	 * when there is no such match both {@code possibleDuplicate} is {@code false} and
14	 * {@code possibleDuplicateOf} is {@code null}.
15	 *
16	 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold} true, which
17	 * deliberately shares an existing owner's household — is never flagged: a declared member is not a
18	 * suspected duplicate. (A non-declared owner sharing a household is rejected outright by
19	 * {@link CheckOwnerIdentityUnique}, so it never reaches this step.)
20	 *
21	 * <p>Runs within the create transaction after {@link BuildOwner} (so the built owner's telephone is
22	 * already in its stored E.164 form) and before {@link SaveOwner} (so {@code findAll} excludes the
23	 * owner being created). When several existing owners match, the one with the lowest id is recorded
24	 * so the result is deterministic. A request without a postcode cannot share one, so it is never a
25	 * possible duplicate.
26	 */
27	public class AssignPossibleDuplicate {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
30	        owner.setPossibleDuplicate(false);
31	        owner.setPossibleDuplicateOf(null);
32	
33	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return; // a declared household member is not a suspected duplicate
35	        }
36	
37	        String postcode = owner.getPostcode();
38	        if (postcode == null || postcode.isBlank()) {
39	            return;
40	        }
41	        String lastName = owner.getLastName();
42	        String telephone = owner.getTelephone();
43	
44	        Owner match = null;
45	        for (Owner existing : ownerRepository.findAll()) {
46	            boolean sameLastName = lastName != null && lastName.equalsIgnoreCase(existing.getLastName());
47	            boolean samePostcode = postcode.equals(existing.getPostcode());
48	            boolean differentTelephone = telephone == null || !telephone.equals(existing.getTelephone());
49	            if (sameLastName && samePostcode && differentTelephone) {
50	                if (match == null || existing.getId() < match.getId()) {
51	                    match = existing;
52	                }
53	            }
54	        }
55	        if (match != null) {
56	            owner.setPossibleDuplicate(true);
57	            owner.setPossibleDuplicateOf(match.getId());
58	        }
59	    }
60	}
