4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Create-time email handling for {@code POST /owners}. Email is optional: an absent (null or
8	 * blank) value is left untouched and the request proceeds. When a value is supplied it must be
9	 * a syntactically valid address (otherwise rejected with 400 via {@link InvalidEmailException})
10	 * and must not use a disposable-email domain (otherwise rejected with 400 via
11	 * {@link DisposableEmailException}). A valid, accepted value is normalised (trimmed and lower-cased) and
12	 * written back onto the body in place (the {@code @Val} object is the same instance
13	 * {@link BuildOwner} then maps), so the lower-cased form is what gets stored and returned.
14	 *
15	 * <p>Runs after {@link NormalizeOwnerTelephone} and before {@link CheckOwnerIdentityUnique}.
16	 */
17	public class NormalizeOwnerEmail {
18	
19	    public void service(@Val OwnerFieldsDto request)
20	            throws InvalidEmailException, DisposableEmailException {
21	        String email = request.getEmail();
22	        if (!OwnerEmail.isPresent(email)) {
23	            return;
24	        }
25	        if (!OwnerEmail.isValid(email)) {
26	            throw new InvalidEmailException(email);
27	        }
28	        if (OwnerEmail.isDisposable(email)) {
29	            throw new DisposableEmailException(email);
30	        }
31	        request.setEmail(OwnerEmail.normalize(email));
32	    }
33	}
